(7228193, 1117286, 96751, '<td valign="top">Somebody has a lot of time on their hands.... Sadly, all the effort to create this wonderful handiwork is undermined by the significant tilt, as this artist''s work was so geometrically perfect.</td>', 'Somebody has a lot of time on their hands.... Sadly, all the effort to create this wonderful handiwork is undermined by the significant tilt, as this artist''s work was so geometrically perfect.', '2014-06-13 03:19:44.000000', NULL, 1),
(7228194, 1116400, 96751, '<td valign="top">This almost looks ''shopped! Very strange, even looks like it''s different lighting!</td>', 'This almost looks ''shopped! Very strange, even looks like it''s different lighting!', '2014-06-13 03:20:22.000000', NULL, 1),
