(7230979, 1117144, 62249, '<td valign="top">A good find. Fits the challenge well.</td>', 'A good find. Fits the challenge well.', '2014-06-19 15:53:14.000000', NULL, 1),
(7230980, 1117255, 62249, '<td valign="top">Clever.</td>', 'Clever.', '2014-06-19 15:53:27.000000', NULL, 1),
(7230982, 1116387, 62249, '<td valign="top">Although not an especially good fit for the challenge, this is still an nteresting photo.</td>', 'Although not an especially good fit for the challenge, this is still an nteresting photo.', '2014-06-19 15:54:43.000000', NULL, 1),
(7230984, 1117364, 62249, '<td valign="top">An unusual interpretation of the challenge theme, but I like it. Well seen!</td>', 'An unusual interpretation of the challenge theme, but I like it. Well seen!', '2014-06-19 15:55:08.000000', NULL, 1),
